# example SQL command to delete duplicates where they exist as a soft delete.
# DELETE FROM taxon_rank
# USING (
#   SELECT rank_name, kingdom_id
#   FROM taxon_rank
#   GROUP BY rank_name, kingdom_id
#   HAVING COUNT(*) > 1) duplicates
# WHERE taxon_rank.deleted_on IS NOT NULL
#   AND taxon_rank.kingdom_id = duplicates.kingdom_id
#   AND taxon_rank.rank_name = duplicates.rank_name;

def generate_command_string(table_name, unique_conditions):
    uc_list = ", "
    uc_list = uc_list.join(unique_conditions)
    and_conditions = ""
    for uc in unique_conditions:
        and_conditions = and_conditions + f'AND "{table_name}".{uc} = duplicates.{uc} '
    command = (
        f'DELETE FROM "{table_name}" '
        f'USING ( SELECT {uc_list} FROM "{table_name}" '
        f"GROUP BY {uc_list} "
        "HAVING count(*)>1) duplicates "
        f'WHERE "{table_name}".deleted = TRUE '
        f"{and_conditions}"
    )
    return command


